@if($modal)<div class="fixed inset-0 z-50 grid place-items-center p-4 bg-black/80"><div class="w-full max-w-2xl max-h-[92vh] overflow-y-auto rounded-2xl bg-zinc-900 border border-zinc-700 p-6"><h2 class="text-lg font-black text-white mb-5">{{ $editingId?'ویرایش فایل':'افزودن فایل به مرکز دانلود' }}</h2><form wire:submit="saveItem" class="space-y-4" x-data="{ uploads: {}, failed: {}, progress: 0 }" x-on:livewire-upload-start="uploads[$event.detail.property] = true; delete failed[$event.detail.property]; progress = 0" x-on:livewire-upload-finish="delete uploads[$event.detail.property]; progress = 100" x-on:livewire-upload-error="delete uploads[$event.detail.property]; failed[$event.detail.property] = true" x-on:livewire-upload-cancel="delete uploads[$event.detail.property]" x-on:livewire-upload-progress="progress = $event.detail.progress" x-on:submit.capture="if (Object.keys(uploads).length || Object.keys(failed).length) { $event.preventDefault(); $event.stopImmediatePropagation() }">@if($errors->any())<div role="alert" class="p-3 rounded-xl bg-rose-500/10 text-rose-300 text-xs"><ul>@foreach($errors->all() as $message)<li>{{ $message }}</li>@endforeach</ul></div>@endif<input wire:model="title" placeholder="عنوان فایل" class="dc-input"><select wire:model="category_id" class="dc-input"><option value="">انتخاب دسته‌بندی</option>@foreach($categories as $c)<option value="{{ $c->id }}">{{ $c->name }}</option>@endforeach</select><input wire:model="short_description" placeholder="توضیح کوتاه" class="dc-input"><textarea wire:model="description" rows="6" placeholder="توضیحات کامل، راهنما، ویژگی‌ها و نکات استفاده" class="dc-input"></textarea><div class="grid md:grid-cols-2 gap-3"><input wire:model="version" placeholder="نسخه" class="dc-input"><input wire:model="platform" placeholder="پلتفرم" class="dc-input"></div><div class="grid md:grid-cols-2 gap-3"><label class="dc-upload">فایل اصلی<input wire:model="file" type="file" wire:key="download-file-{{ $editingId ?? 'new' }}" x-on:change="if ($event.target.files.length) { uploads.file = true; delete failed.file }"></label><label class="dc-upload">تصویر کاور<input wire:model="cover" type="file" accept="image/jpeg,image/png,image/webp" wire:key="download-cover-{{ $editingId ?? 'new' }}" x-on:change="if ($event.target.files.length) { uploads.cover = true; delete failed.cover }"></label></div><p class="text-xs text-zinc-500">فایل تا ۱۰۰ مگابایت؛ کاور JPG، PNG یا WebP تا ۵ مگابایت.</p><p class="text-[11px] text-zinc-500">محدودیت فعال PHP این درخواست: فایل {{ ini_get('upload_max_filesize') }} / کل درخواست {{ ini_get('post_max_size') }}. محدودیت وب‌سرور نیز باید با این مقادیر هماهنگ باشد.</p><div x-show="Object.keys(uploads).length" x-cloak class="rounded-xl border border-brand-500/30 bg-brand-500/10 p-3" role="status"><p class="text-xs text-brand-300">در حال بارگذاری… <span x-text="progress + '%'" dir="ltr"></span>؛ تا پایان آپلود صبر کنید.</p><progress :value="progress" max="100" class="w-full h-2 mt-2"></progress></div><div x-show="Object.keys(failed).length" x-cloak role="alert" class="rounded-xl bg-rose-500/10 p-3 text-xs text-rose-300">بارگذاری به سرور ناموفق بود. فایل را دوباره انتخاب کنید. محدودیت حجم PHP و وب‌سرور، اتصال اینترنت و فضای ذخیره‌سازی را بررسی کنید.</div>@if($uploadedFileInfo)<div class="rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-3 text-xs text-emerald-300" role="status">✓ فایل اصلی دریافت شد: <span dir="ltr">{{ $uploadedFileInfo['name'] }}</span> — {{ number_format($uploadedFileInfo['size'] / 1048576, 2) }} مگابایت</div>@elseif($editingId)<p class="text-xs text-zinc-400">در صورت انتخاب نکردن فایل جدید، فایل اصلی قبلی حفظ می‌شود.</p>@endif @if($uploadedCoverInfo && isset($uploadedCoverInfo['preview']))<div class="flex items-center gap-3 rounded-xl border border-zinc-700 p-3"><img src="{{ $uploadedCoverInfo['preview'] }}" alt="پیش‌نمایش کاور" class="w-20 h-20 rounded-xl object-cover"><span class="text-xs text-emerald-300">✓ تصویر کاور دریافت شد</span></div>@endif<div class="flex gap-4 text-sm text-zinc-300"><label><input wire:model="is_published" type="checkbox"> انتشار</label><label><input wire:model="is_featured" type="checkbox"> ویژه</label></div><div class="flex gap-3 pt-4"><button type="button" wire:click="$set('modal',false)" class="flex-1 py-3 rounded-xl bg-zinc-800 text-zinc-300">انصراف</button><button type="submit" :disabled="Object.keys(uploads).length > 0 || Object.keys(failed).length > 0" wire:loading.attr="disabled" wire:target="file,cover,saveItem" class="flex-1 ui-button disabled:opacity-50">ذخیره فایل</button></div></form></div></div>@endif
@if($categoryModal)<div class="fixed inset-0 z-50 grid place-items-center p-4 bg-black/80"><div class="w-full max-w-md rounded-2xl bg-zinc-900 border border-zinc-700 p-6"><h2 class="text-lg font-black text-white mb-5">دسته‌بندی دانلود</h2><form wire:submit="saveCategory" class="space-y-4">@if($errors->any())<div role="alert" class="text-xs text-rose-300">@foreach($errors->all() as $message)<p>{{ $message }}</p>@endforeach</div>@endif<input wire:model="categoryName" placeholder="نام دسته‌بندی" class="dc-input"><input wire:model="categoryIcon" placeholder="آیکون یا Emoji" class="dc-input"><textarea wire:model="categoryDescription" placeholder="توضیح دسته‌بندی" class="dc-input"></textarea><div class="flex gap-3"><button type="button" wire:click="$set('categoryModal',false)" class="flex-1 py-3 rounded-xl bg-zinc-800 text-zinc-300">انصراف</button><button class="flex-1 ui-button">ذخیره</button></div></form></div></div>@endif<style>.dc-input{width:100%;background:#080f1d;border:1px solid #334155;border-radius:.75rem;color:#e2e8f0;padding:.75rem;font-size:.85rem}.dc-input:focus{outline:2px solid #3b82f655}.dc-upload{display:block;border:1px dashed #475569;border-radius:.75rem;padding:1rem;text-align:center;color:#94a3b8;font-size:.75rem}.dc-upload input{display:block;width:100%;margin-top:.5rem;font-size:.7rem}</style></div>
